def solve():
    n = int(input())
    graph = defaultdict(list)
    min_heap = []
    max_heap = []

    for _ in range(n):
        a, b = map(int, input().split())
        graph[a].append(b)

    for i in range(201):
        if not graph[i]:
            continue
        heappush(min_heap, (i, b) for b in graph[i])
        heappush(max_heap, (-i, b) for b in graph[i])

    count = 0
    while True:
        a, b = heappop(max_heap)
        if a + b > 0:
            heappush(max_heap, (-a, b))
        else:
            count += 1
            heappush(min_heap, (a, b))
            if a!= 0 and graph[a]:
                heappush(max_heap, (-a, b))
        if not min_heap:
            break
        a, b = heappop(min_heap)
        if a < b:
            heappush(min_heap, (a, b))
        else:
            count += 1
            heappush(max_heap, (-a, b))

    print(count)

