def solve(n, m, posts):
    # Create a set of recent posts
    recent_posts = set(range(1, n + 1))

    # Initialize the order of recent posts
    order = list(recent_posts)

    # Process each post
    for i, post in enumerate(posts):
        if post in recent_posts:
            # If post is in recent posts, move it to the top
            order.remove(post)
            order.insert(0, post)
        else:
            # If post is not in recent posts, add it to the top and remove the oldest post
            order.append(post)
            order.pop()

    # Find the first time each post is removed
    removed_times = {}
    for i, post in enumerate(order):
        if post in recent_posts:
            removed_times[post] = i + 1

    return [removed_times.get(i, -1) for i in range(1, n + 1)]

