def solve(a):
    even_sum = sum(i % 2 == 0 for i in a)
    odd_sum = len(a) - even_sum

    if even_sum % 2 == 0:
        return 0

    if odd_sum == 0:
        return sys.maxsize

    operations = 0
    for num in a:
        if num % 2 == 0:
            continue
        while num % 2!= 0:
            num = num // 2
            operations += 1
        if (even_sum + (len(a) - odd_sum - 1)) % 2 == 0:
            break
        even_sum += 1
        odd_sum -= 1

    return operations

