from typing import List

def solve(nums: List[int]) -> int:
    def permutation(start: int, end: int, path: List[int], result: int):
        if start > end:
            result = 0
            for x in path:
                if result < x:
                    result += x
                else:
                    result = 0
            return result
        for i in range(start, end + 1):
            if nums[i - 1] > 0:
                path.append(nums[i - 1])
                permutation(start, i - 1, path, result)
                path.pop()
        return result
    result = 0
    path = []
    nums.sort(reverse=True)
    result = permutation(0, len(nums) - 1, path, result)
    print(*nums)

