from functools import lru_cache

def solve(s):
    @lru_cache(maxsize=None)
    def dfs(n, used, current):
        if n == 0:
            return current
        result = float('inf')
        for i in range(10):
            if not used[i]:
                new_used = used.copy()
                new_used[i] = True
                new_current = current * 10 + i
                result = min(result, dfs(n - 1, new_used, new_current))
        return result

    return dfs(s, [False] * 10, 0)

