            else:
                x = 0
            if y == 0:
                y = float('inf')
            else:
                y = 0
            positions.append((x, y))
        heapq.heapify(positions)
        steps = 0
        while positions:
            pos = heapq.heappop(positions)
            steps += abs(pos[0]) + abs(pos[1])
            if (0, pos[0]) in positions:
                heapq.heappop(positions)
            if (pos[1], 0) in positions:
                heapq.heappop(positions)
        results.append(steps)
    print('\n'.join(map(str, results)))

